import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"WorldGym: World Model as An Environment for Policy Evaluation","description":"","frontmatter":{"title":"WorldGym: World Model as An Environment for Policy Evaluation","arxiv":"2506.00613","date":"2025-05-31","authors":"Julian Quevedo, Ansh Kumar Sharma, Yixiang Sun, Varad Suryavanshi, Percy Liang, Sherry Yang","categories":"cs.RO, cs.AI","topics":"世界模型评测, 动作条件视频生成, 策略评估","outline":[2,2]},"headers":[],"relativePath":"papers/2506.00613.md","filePath":"papers/2506.00613.md","lastUpdated":null}'),l={name:"papers/2506.00613.md"};function e(m,s,r,i,c,o){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="worldgym-world-model-as-an-environment-for-policy-evaluation" tabindex="-1">WorldGym: World Model as An Environment for Policy Evaluation <a class="header-anchor" href="#worldgym-world-model-as-an-environment-for-policy-evaluation" aria-label="Permalink to &quot;WorldGym: World Model as An Environment for Policy Evaluation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2506.00613" target="_blank" rel="noreferrer">2506.00613</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-05-31</td></tr><tr><td><strong>作者</strong></td><td>Julian Quevedo, Ansh Kumar Sharma, Yixiang Sun, Varad Suryavanshi, Percy Liang, Sherry Yang</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>用一个 Diffusion-Forcing 训练的动作条件自回归视频模型当&quot;生成式仿真器&quot;，只给一张真实初始帧就让 VLA 策略在里面 rollout，再用 GPT-4o 当奖励函数打成功率。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文基于 arXiv <strong>v3</strong>（2025-09-30）全文撰写。本站论文索引记作 &quot;Evaluating Robot Policies in a World Model&quot;，v3 的正式标题已改为 <em>WorldGym: World Model as An Environment for Policy Evaluation</em>，系作者改名而非编号错误。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>机器人策略的评测是一件昂贵到扭曲研究节奏的事。真机评测要人守着复位、要几天时间、要承担撞坏硬件的风险；手写仿真器要人力逐个建模场景与接触动力学，而 sim-to-real gap 让结论未必迁移。这直接导致一个后果：大部分 VLA 论文的真机数字建立在每格 10 次试验上，噪声大到无法支撑细粒度的设计决策。</p><p>本文提出的替代方案是：既然视频生成模型已经能被动作条件化，那就把它当成环境。策略吐动作，视频模型吐下一帧，循环几百步，最后让一个 VLM 看这段生成视频判定任务是否完成。这个方案的诱人之处在于它只需要<strong>一张真实初始帧</strong>——想测新场景就用图像编辑模型改一改那张帧，想测新指令就换一句话，不需要任何真机布置。</p><p>论文的核心经验主张是：这样得到的成功率与真机成功率高度相关（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.78</span></span></span></span>），且跨版本、跨规模、跨训练 checkpoint 的相对排序被保持。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>动作条件视频生成</strong>。UniSim、Genie、Oasis、GameNGen 等已证明视频模型能被文本或按键条件化并做长时交互；Cosmos 开始把它用到机器人控制上。但这些工作停在&quot;能生成得像&quot;，没有把它用作<strong>定量</strong>的策略评估器。</p><p><strong>离线策略评估（OPE）</strong>。这一支有几十年积累（重要性采样、双重稳健、FQE），但绝大多数实验设定假设全可观、可拿到真值状态、单一任务。真机的图像观测、高控制频率、跨任务跨环境的数据分布都不满足这些前提。基于模型的 OPE 一直被认为不划算：单任务下学动力学比学价值更难，且 rollout 会累积误差。</p><p><strong>基于仿真的代理评测</strong>。SIMPLER 从真实图像构建软件仿真器，并展示了与真机高度相关的曲线，是最接近的对照。它的局限是：要测 OOD 语言或 OOD 视觉输入就得手工改仿真器，工程量大。</p><p>本文的观察是对&quot;单任务下动力学比价值难学&quot;这一判断的反驳：任务和策略可以有无数个，但物理世界只有一个。因此一个世界模型可以摊销到所有任务上，这个论证是本文最有价值的 framing。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>不用本文结论。事实一：Open-X Embodiment 汇聚了跨形态、跨任务的大规模真机轨迹，每条都带同步的动作标签——这正好是训练动作条件视频模型的原料，而且它是&quot;一个世界、多种任务&quot;的字面实例。事实二：Diffusion Forcing 让每帧带独立噪声水平，从而在同一个模型里既能自回归又能并行去噪任意长度的片段。事实三：不同 VLA 输出的动作块长度不同（RT-1 逐步、Octo 与 OpenVLA 成块），而固定上下文长度的双向视频模型（如 Cosmos）必须每次去噪固定 16 帧，短块浪费算力、长块无法并行。</p><p>把三条拼起来：用 Diffusion Forcing + 因果时间注意力训一个动作条件模型，推理时把去噪视界长度<strong>设成策略的动作块长度</strong>，就能用一个 checkpoint 高效服务所有策略。剩下的缺口是奖励——真机评测靠人看，生成视频里没有物理状态可查，唯一现成的替代品是 VLM。这条路径不需要预设&quot;世界模型评测有效&quot;。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>评测一个策略不需要模拟真实物理，只需要模拟<strong>策略会遇到的观测分布</strong>，并且把&quot;任务是否完成&quot;这件事判对。世界模型不必知道摩擦系数是多少，它只要在给定动作序列时渲染出与真机相似的画面演化即可；而&quot;是否完成&quot;这个判断本来在真机评测里就是人眼给的，换成 VLM 是同一类判断。于是评测被拆成两个都已经被解决的子问题：动作条件视频生成，与视觉问答。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以在 Bridge WidowX 上评测 OpenVLA 的&quot;把茄子放进锅里&quot;为例。</p><ul><li><strong>世界模型训练</strong>。潜空间 Diffusion Transformer，用 Diffusion Forcing 支持自回归生成。每帧的机器人动作向量线性投影到模型维度，与扩散时间步 embedding <strong>逐元素相加</strong>，再通过 AdaLN-Zero 调制（与 DiT 的类条件同构）。历史帧 latent 通过因果时间注意力块接入，时间块与空间注意力块交错。为了保证可控性，训练时<strong>整段随机丢弃动作</strong>，推理时用 classifier-free guidance 强化对动作的服从。</li><li><strong>推理循环</strong>。给定真实初始帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> → 策略输出动作块 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7305em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathbf">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pred</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> → 世界模型把去噪视界设为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord">∣</span><span class="mord"><span class="mord mathbf">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pred</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord">∣</span></span></span></span>，一次并行生成对应帧数 → 取最后一帧回给策略。反复数百步。</li><li><strong>奖励</strong>。把整段生成 rollout 的帧序列与语言指令交给 GPT-4o，按预设 rubric 判定成功；部分任务有&quot;部分得分&quot;准则（例如朝目标移动记 0.5）。</li><li><strong>世界模型自身的验证</strong>。（i）在 Open-X 验证集上用与真实视频相同的动作序列生成，定性比对 Bridge / RT-1 / VIOLA / Berkeley UR5 四种形态；（ii）末端控制扫描：手工构造&quot;只动一个动作维度、其余置零&quot;的控制序列（训练数据中不存在这类序列），检查生成视频是否沿该维度运动、夹爪是否开合。</li><li><strong>策略评测</strong>。对照 OpenVLA 论文的 Bridge 评测套件：17 个任务、每任务 10 次试验，取其录像的第一帧作为世界模型的初始帧，逐条重放。评测 RT-1-X、Octo、OpenVLA。全部 rollout 在单卡一小时内跑完。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>策略价值的定义与蒙特卡洛估计是标准的：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">ρ</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathbb">E</span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">G</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">]</span></span><span class="mpunct">,</span></span></span></span></span></p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">ρ</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2968em;vertical-align:-0.35em;"></span><span class="mord mathbb">E</span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mopen">([</span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">G</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0519em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mopen">(</span><span class="mord mathbf">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8019em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1968em;vertical-align:-0.25em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathbf">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">a</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">o</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8019em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">]</span></span><span class="mord">.</span></span></span></span></span></p><p>真正值得推的是相关系数本身。<strong>下面这段是笔者根据论文表 5 的逐格数据自行计算，论文未给出。</strong> 表 5 提供 3 个策略 × 17 个任务 = 51 个 (真机成功数, WorldGym 成功数) 配对。按这 51 个点算得 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.785</span></span></span></span>，与论文报告的 0.78 一致。把协方差做组间/组内分解：</p><ul><li>总交叉积 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">x</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">361.6</span></span></span></span>，其中<strong>组间（三个策略均值之差）部分为 278.2，占 77%</strong>；</li><li>组内（固定策略、跨 17 个任务）部分仅 83.4，对应组内相关 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">within</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.465</span></span></span></span>；</li><li>若构造一个<strong>完全忽略任务、只输出该策略在 WorldGym 里的平均成功率</strong>的平凡预测器，它与真机逐任务成功率的相关是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.752</span></span></span></span>。</li></ul><p>也就是说，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.78</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.752</span></span></span></span> 的差距，才是&quot;WorldGym 逐任务预测&quot;相对&quot;只知道是哪个策略&quot;的全部增量。这不是说 WorldGym 无用——它恰恰是<strong>产生</strong>那三个均值的东西——但它说明表 5 那张散点图的高相关主要由 OpenVLA（约 70%）与另外两个策略（约 19%–20%）之间的巨大落差撑起，逐任务的分辨力要弱得多。逐格反例也支持这一点：OpenVLA 的 Lift White Tape 真机 1 次成功、WorldGym 6 次；Put Carrot on Plate 真机 8 次、WorldGym 4 次；Octo 的 Flip Pot Upright 真机 6 次、WorldGym 1 次。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：世界模型本身可控吗？</strong> 验证集重放与单维控制扫描都通过，且单维序列不在训练数据中，说明模型不是在记忆轨迹。这部分全为定性。</p><p><strong>问题二：策略值与真机相关吗？</strong> 均值层面：RT-1-X 真机 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">18.5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">4.0%</span></span></span></span> vs WorldGym <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">15.5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">3.4%</span></span></span></span>；Octo <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">20.0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">5.3%</span></span></span></span> vs <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">23.82</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">4.3%</span></span></span></span>；OpenVLA <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">70.6</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">6.1%</span></span></span></span> vs <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">67.4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">4.9%</span></span></span></span>，平均偏差 3.3%。逐任务 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.78</span></span></span></span>。需要如实指出：<strong>真机上 RT-1-X 与 Octo 的差距是 1.5 个百分点，而两者的标准误分别是 4.0 与 5.3</strong>——这一对的&quot;真实排序&quot;本身就在噪声里，因此&quot;排序被保持&quot;这一说法在这两个策略之间意义有限；OpenVLA 与另两者的排序则远在噪声之外。</p><p><strong>问题三：能否保持已知排序？</strong> 版本/规模：Octo-Small 1.5 &lt; Octo-Base 1.5，OpenVLA v0.1 7B（欠训开发版）&lt; OpenVLA 7B，方向与真机文献一致。训练进程：自训的 UniPi 式视频策略（2K/8K/12K/18K 步）与 DexVLA 式扩散策略（10K/20K/40K/60K 步）在 WorldGym 上的成功率随训练步数上升，与其验证集 MSE 下降一致。这两组都只有柱状图。</p><p>在 Google Robot 的 RT-1 子集（表 4，4 个任务 × 10 次）上，合计成功数 RT-1-X 20、Octo 20.5、OpenVLA 22.5，差距远比 Bridge 小；且 Close Bottom Drawer 一项 RT-1-X 9 &gt; Octo 8.5 &gt; <strong>OpenVLA 6</strong>，与总体排序相反。这一组<strong>没有对应的真机参照</strong>，因此不能用来支持&quot;排序保持&quot;。</p><p><strong>问题四：OOD 探索。</strong> 用 Nano Banana 编辑初始帧：（i）同时放入胡萝卜与橙子并要求拿橙子，OpenVLA 抓离得近的那个，把胡萝卜改成红色后才总能抓对橙子——提示它靠颜色而非形状区分；（ii）加一台显示胡萝卜图片的笔记本，OpenVLA 在 <strong>15%</strong> 的试验里去抓屏幕上的胡萝卜；（iii）红/蓝纸片分类，OpenVLA 全对，Octo 与 RT-1 接近随机；更难的方块/圆形、名人脸、猫狗分类，所有策略都接近随机。给全部 17 个任务的初始帧加无关干扰物后，RT-1-X 掉 51%、Octo 掉 83%、OpenVLA 掉 41.5%。OOD 语言（表 1，每格 10 次）：Move Pot Into Drying Rack 3/0/7、Move The Pot To The Counter 0/0/1、Put Plate On Drying Rack 4/2/8、Put Yellow Corn In Red Cup 1/2/3。</p><p><strong>奖励模型的验证。</strong> 附录 B.2 在 RT-1 <strong>真实</strong>视频上用真值成功标签检验 GPT-4o：TP <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.81</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.14</span></span></span></span>、FN <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.19</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.14</span></span></span></span>、FP <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.03</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.05</span></span></span></span>、TN <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.97</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.05</span></span></span></span>（4 次运行）。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版。</strong> WorldGym 用一个 Diffusion-Forcing 训练的动作条件视频模型充当生成式仿真器，把去噪视界对齐到策略的动作块长度，从而用单个 checkpoint 服务不同动作块长度的策略。奖励由 GPT-4o 从生成视频判定。三个 VLA 在 17 个 Bridge 任务上的成功率与真机的逐任务相关为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.78</span></span></span></span>，均值偏差 3.3%，跨版本/规模/训练步数的相对排序被保持。只需要一张初始帧这一特性，使它能用图像编辑模型批量造 OOD 场景，由此发现现有 VLA 靠颜色而非形状区分物体、会被物体的二维&quot;外壳&quot;（屏幕上的图片）骗到。全部 rollout 单卡一小时可跑完，而真机评测通常要几天。</p><p><strong>3 句话版。</strong> 把动作条件视频模型当环境、把 VLM 当裁判，可以在一小时内复现出与真机高度相关的策略排序。相关性主要由策略之间的大落差撑起，逐任务的分辨力弱得多（组内相关约 0.47）。最大的未验证环节是：奖励模型只在真实视频上校准过，从未在生成视频上测过。</p><p><strong>1 句话版。</strong> 世界只有一个，所以世界模型可以摊销到所有任务和所有策略上做评测。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱且承重最大的假设是：<strong>GPT-4o 在生成视频上的判定准确率与在真实视频上相当。</strong></p><p>论文报告的每一个成功率——包括 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.78</span></span></span></span>、3.3% 的均值偏差、全部 OOD 结论——都是这个奖励模型在<strong>生成</strong>视频上打出来的。而唯一的校准实验（附录表 3）用的是 RT-1 的<strong>真实</strong>视频。这两个分布最关键的差别恰恰在于：生成视频里会出现真实视频中不可能出现的失效模式——物体在夹爪闭合前就&quot;吸&quot;上去、被抓物体形变或穿模、放下后又漂回原位。这些正是最容易让 VLM 判成&quot;成功&quot;的伪影，因为画面的<strong>语义结果</strong>看起来是对的，只是过程在物理上不可能。</p><p>叠加一个结构性偏置：世界模型训练在 Open-X 上，而 Open-X 绝大部分是<strong>成功的</strong>演示。给定一段还算合理的动作序列，模型的条件分布天然偏向&quot;任务完成&quot;这个结局。这两件事叠在一起，指向的是同一种误差——生成视频上的假阳性，而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">ρ</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span> 恰恰会被假阳性系统性抬高。</p><p>论文给了什么证据？表 3 的低假阳性率（0.03）只在真实视频上成立，不能外推。逐格数据里既有高估（Octo 均值 20.0→23.82；OpenVLA Lift White Tape 1→6）也有低估（OpenVLA Put Carrot on Plate 8→4），方向混杂，说明误差不是单纯的偏置而是较大的方差——但这本身也提示逐任务估计不可靠。缺什么证据？缺一个直接的实验：让人类标注一批<strong>生成</strong>的 rollout，与 GPT-4o 的判定比混淆矩阵。这是全文最应该做而没做的一步。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要重训世界模型，一周可完成。</p><ol><li>从论文开源的 WorldGym rollout 里随机抽 200 段（覆盖三个策略、17 个任务），由 3 名标注者独立判定成功/失败，取多数票为真值，同时记录标注者一致率。</li><li>用同一个 GPT-4o prompt 打分，算混淆矩阵，与附录表 3（真实视频）逐格对比。</li><li>关键判据：若生成视频上的<strong>假阳性率</strong>显著高于 0.03（比如超过 0.15），则所有报告的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">ρ</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span> 都被系统性抬高，且抬高幅度与策略的&quot;动作看起来合理程度&quot;相关——这会同时解释为什么弱策略（Octo 20.0→23.82）被高估、强策略（OpenVLA 70.6→67.4）反而被低估。</li><li>附加一项（半天，纯计算）：用 §6 的分解方法，把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 拆成组间/组内，并报告&quot;只输出策略均值&quot;这一平凡基线的相关。任何后续声称&quot;世界模型评测与真机高相关&quot;的工作都应该同时报告这两个数，否则读者无法判断相关性来自任务分辨力还是策略间落差。</li></ol><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的替代解释是：<strong><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.78</span></span></span></span> 主要是&quot;OpenVLA 比另外两个强得多&quot;这一件事的产物，而不是 WorldGym 在任务粒度上有预测力。</strong></p><p>笔者从表 5 算出的分解直接支持这一点：51 个点的协方差里 77% 来自三个策略均值之差，固定策略后的组内相关只有 0.465，而&quot;忽略任务、只输出策略均值&quot;的平凡预测器就能拿到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.752</span></span></span></span>。换句话说，一个只知道&quot;这是 OpenVLA 还是 Octo&quot;的评估器，几乎能复现论文的头条相关系数。</p><p>第二条支撑来自 Google Robot（表 4）：那里三个策略的差距被压缩到 50%/51.25%/56.25%，而排序在单个任务上就会翻转（Close Bottom Drawer：RT-1-X 9 &gt; Octo 8.5 &gt; OpenVLA 6）。这正是&quot;当策略间落差变小时，评估器的分辨力不够&quot;的预期表现，而该组没有真机参照可供核对。</p><p>第三条：真机上 RT-1-X（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">18.5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4.0</span></span></span></span>）与 Octo（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">20.0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">±</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5.3</span></span></span></span>）的差距远小于标准误，所谓&quot;三个策略的排序被保持&quot;实际上只有一对（OpenVLA vs 其余）是有统计意义的。</p><p>判决性实验：构造一族<strong>成功率连续可调</strong>的策略——例如取 OpenVLA，按概率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.5</span><span class="mclose">}</span></span></span></span> 把它的输出动作替换成高斯噪声，得到 6 个真实成功率大致均匀铺开的策略。在真机（或至少在 SIMPLER 这类已验证的仿真器）与 WorldGym 上分别评测，再算相关与 MMRV 这类排序反转度量。如果在这种&quot;没有天然大落差&quot;的策略族上相关掉到 0.5 以下，那么 WorldGym 目前的定位应当被限定为&quot;粗筛&quot;而非&quot;排序&quot;。</p><p>另一个可预测的失败场景：评测两个成功率相近但失败模式不同的策略（一个抓不稳、一个抓错物体）。世界模型对&quot;抓不稳&quot;这种接触相关的失效渲染能力最弱（论文自己承认&quot;生成高度真实的物体交互仍然困难&quot;），因此会系统性地低估抓取稳定性问题、相对高估语义错误——两个策略的排序会朝可预测的方向偏。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：WorldGym 现在给出的是一个点估计 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">ρ</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span>，没有任何&quot;这个估计可不可信&quot;的伴随信号。而它的两个误差源——世界模型的动力学幻觉与 VLM 裁判的误判——性质完全不同，却被压成同一个标量。当估计出错时，使用者既不知道错了，也不知道该去修哪一环。</p><p><strong>新的 framing</strong>：把世界模型评测重新表述为一个<strong>带弃权的预测问题</strong>，并给它配一个有严格覆盖率保证的置信区间。具体地，用保形预测（conformal prediction）：拿一小批<strong>有真机真值</strong>的策略-任务对做校准集，在世界模型的 rollout 上定义一个非一致性分数（例如&quot;<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 次 rollout 的成功率方差 + VLM 判定的 logit 熵 + 世界模型逐帧去噪残差&quot;的组合），从而对每个新的策略-任务对输出一个区间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">ρ</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">lo</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">ρ</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">hi</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span></span></span></span>，并允许在区间过宽时<strong>弃权</strong>（&quot;这个任务我判不了，请去真机测&quot;）。这把评测器从&quot;替代真机&quot;变成&quot;决定哪些格子值得上真机&quot;，而后者的实用价值可能更高——真机预算是有限的，最优分配才是真问题。</p><p><strong>可借鉴的相邻领域工具</strong>：（a）保形预测与风险控制（conformal risk control）已有针对&quot;分布偏移下的覆盖率&quot;的成熟变体，正好对应 OOD 初始帧这一场景；（b）主动学习/最优实验设计里的信息增益准则，可以直接用来排序&quot;该先在真机上测哪几格&quot;；（c）LLM 评审的校准文献（自一致性、多裁判投票）为把 VLM 那一环的不确定性单独量化提供了现成方法。</p><p><strong>第一个实验</strong>：仍用表 5 的 51 个策略-任务对，把它们随机划成校准集（比如 20 格）与测试集（31 格）。在测试集上输出 90% 覆盖率的区间，度量三项：实际覆盖率、平均区间宽度、以及&quot;在只允许上真机测 10 格的预算下，按不确定性排序选格 vs 随机选格，能把估计误差降低多少&quot;。如果不确定性排序能把误差降低一半以上，就说明世界模型评测最有价值的输出不是那个成功率，而是它对自己的怀疑。同期的 <a href="/notes/papers/2506.00411">LoHoVLA</a> 依赖仿真器逐步真值奖励做闭环，正是这类&quot;用生成式评估器替代特权信号&quot;最直接的下游用户；更早的 <a href="/notes/papers/2606.18610">SC3-Eval</a> 与 <a href="/notes/papers/2602.08971">WorldArena</a> 也各自独立报告过世界模型评估器系统性高估成功率的现象。</p>',59)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
